cd /tmp/opencode && cat > /tmp/opencode/attacktest.js <<'EOF'
async (page) => {
  const read = () => page.evaluate(() => window.AO_DEBUG());
  let state = await read();
  let target = state.fighters.find(f => f.id === 'chaoticWarrior');
  for (let i = 0; i < 80 && target?.alive; i++) {
    const p = state.fighters.find(f => f.id === 'player');
    target = state.fighters.find(f => f.id === 'chaoticWarrior');
    if (!p?.alive || !target?.alive) break;
    const dx = target.x - p.x, dy = target.y - p.y;
    if (Math.abs(dx) + Math.abs(dy) <= 1) break;
    const key = Math.abs(dx) >= Math.abs(dy) ? (dx > 0 ? 'ArrowRight' : 'ArrowLeft') : (dy > 0 ? 'ArrowDown' : 'ArrowUp');
    await page.keyboard.down(key);
    await page.waitForTimeout(230);
    await page.keyboard.up(key);
    await page.waitForTimeout(30);
    state = await read();
  }
  state = await read();
  const p = state.fighters.find(f => f.id === 'player');
  const t = state.fighters.find(f => f.id === 'chaoticWarrior');
  const before = t?.hp ?? null;
  const distance = p && t ? Math.abs(t.x - p.x) + Math.abs(t.y - p.y) : null;
  await page.keyboard.press('f');
  await page.waitForTimeout(70);
  const afterState = await read();
  const after = afterState.fighters.find(f => f.id === 'chaoticWarrior')?.hp ?? null;
  return { distance, before, after, delta: before != null && after != null ? before - after : null, recentTexts: afterState.texts, player: afterState.fighters.find(f=>f.id==='player'), target: afterState.fighters.find(f=>f.id==='chaoticWarrior') };
}
EOF
